// Signs each form submission for the CRM's Website form connection, the
// Standard Webhooks way. Paste the connection's signing secret below. On n8n
// plans with Variables, use $vars.CRM_FORM_SECRET instead, so exported copies
// of this workflow leave the secret out.
const secret = 'PASTE_THE_SIGNING_SECRET';
const crypto = require('crypto');
if (!secret.startsWith('whsec_')) {
  throw new Error("Paste the signing secret from the CRM's Website form connection.");
}
const key = Buffer.from(secret.slice('whsec_'.length), 'base64');

return $input.all().map((item) => {
  const form = item.json.body || {};
  // Change the names on the right to the field names your form sends.
  const submission = {
    name: form.name,
    email: form.email,
    phone: form.phone,
    message: form.message,
    form: form.form || 'Website form',
    source: form.source || form.utm_source,
    utm_campaign: form.utm_campaign,
  };
  // JSON.stringify leaves out fields the form did not send. The CRM checks the
  // signature against these exact bytes, so send `payload` unchanged.
  const payload = JSON.stringify(submission);
  const id = `msg_${crypto.randomUUID()}`;
  const timestamp = String(Math.floor(Date.now() / 1000));
  const hmac = crypto.createHmac('sha256', key).update(`${id}.${timestamp}.${payload}`);
  return { json: { payload, id, timestamp, signature: `v1,${hmac.digest('base64')}` } };
});
